-- ----------------------------
-- 18、代码生成业务表
-- ----------------------------
drop table if exists gen_table;
create table gen_table (
  table_id          bigint(20)      not null auto_increment    comment '编号',
  table_name        varchar(200)    default ''                 comment '表名称',
  table_comment     varchar(500)    default ''                 comment '表描述',
  sub_table_name    varchar(64)     default null               comment '关联子表的表名',
  sub_table_fk_name varchar(64)     default null               comment '子表关联的外键名',
  class_name        varchar(100)    default ''                 comment '实体类名称',
  tpl_category      varchar(200)    default 'crud'             comment '使用的模板（crud单表操作 tree树表操作）',
  tpl_web_type      varchar(30)     default ''                 comment '前端模板类型（element-ui模版 element-plus模版）',
  package_name      varchar(100)                               comment '生成包路径',
  module_name       varchar(30)                                comment '生成模块名',
  business_name     varchar(30)                                comment '生成业务名',
  function_name     varchar(50)                                comment '生成功能名',
  function_author   varchar(50)                                comment '生成功能作者',
  gen_type          char(1)         default '0'                comment '生成代码方式（0zip压缩包 1自定义路径）',
  gen_path          varchar(200)    default '/'                comment '生成路径（不填默认项目路径）',
  options           varchar(1000)                              comment '其它生成选项',
  create_by         varchar(64)     default ''                 comment '创建者',
  create_time 	    datetime                                   comment '创建时间',
  update_by         varchar(64)     default ''                 comment '更新者',
  update_time       datetime                                   comment '更新时间',
  remark            varchar(500)    default null               comment '备注',
  primary key (table_id)
) engine=innodb auto_increment=1 comment = '代码生成业务表';


-- ----------------------------
-- 19、代码生成业务表字段
-- ----------------------------
drop table if exists gen_table_column;
create table gen_table_column (
  column_id         bigint(20)      not null auto_increment    comment '编号',
  table_id          bigint(20)                                 comment '归属表编号',
  column_name       varchar(200)                               comment '列名称',
  column_comment    varchar(500)                               comment '列描述',
  column_type       varchar(100)                               comment '列类型',
  java_type         varchar(500)                               comment 'JAVA类型',
  java_field        varchar(200)                               comment 'JAVA字段名',
  is_pk             char(1)                                    comment '是否主键（1是）',
  is_increment      char(1)                                    comment '是否自增（1是）',
  is_required       char(1)                                    comment '是否必填（1是）',
  is_insert         char(1)                                    comment '是否为插入字段（1是）',
  is_edit           char(1)                                    comment '是否编辑字段（1是）',
  is_list           char(1)                                    comment '是否列表字段（1是）',
  is_query          char(1)                                    comment '是否查询字段（1是）',
  query_type        varchar(200)    default 'EQ'               comment '查询方式（等于、不等于、大于、小于、范围）',
  html_type         varchar(200)                               comment '显示类型（文本框、文本域、下拉框、复选框、单选框、日期控件）',
  dict_type         varchar(200)    default ''                 comment '字典类型',
  sort              int                                        comment '排序',
  create_by         varchar(64)     default ''                 comment '创建者',
  create_time 	    datetime                                   comment '创建时间',
  update_by         varchar(64)     default ''                 comment '更新者',
  update_time       datetime                                   comment '更新时间',
  primary key (column_id)
) engine=innodb auto_increment=1 comment = '代码生成业务表字段';
-- END SOURCE: ry_20250522.sql

-- ============================================================================
-- BEGIN SOURCE: quartz.sql
-- SHA256: 68ddc1c2dcd003e5a5470d88f23bfe8daee54d2b6ae77c720e5b82f8dd57ef0a
-- ============================================================================
DROP TABLE IF EXISTS QRTZ_FIRED_TRIGGERS;
DROP TABLE IF EXISTS QRTZ_PAUSED_TRIGGER_GRPS;
DROP TABLE IF EXISTS QRTZ_SCHEDULER_STATE;
DROP TABLE IF EXISTS QRTZ_LOCKS;
DROP TABLE IF EXISTS QRTZ_SIMPLE_TRIGGERS;
DROP TABLE IF EXISTS QRTZ_SIMPROP_TRIGGERS;
DROP TABLE IF EXISTS QRTZ_CRON_TRIGGERS;
DROP TABLE IF EXISTS QRTZ_BLOB_TRIGGERS;
DROP TABLE IF EXISTS QRTZ_TRIGGERS;
DROP TABLE IF EXISTS QRTZ_JOB_DETAILS;
DROP TABLE IF EXISTS QRTZ_CALENDARS;

-- ----------------------------
-- 1、存储每一个已配置的 jobDetail 的详细信息
-- ----------------------------
create table QRTZ_JOB_DETAILS (
    sched_name           varchar(120)    not null            comment '调度名称',
    job_name             varchar(200)    not null            comment '任务名称',
    job_group            varchar(200)    not null            comment '任务组名',
    description          varchar(250)    null                comment '相关介绍',
    job_class_name       varchar(250)    not null            comment '执行任务类名称',
    is_durable           varchar(1)      not null            comment '是否持久化',
    is_nonconcurrent     varchar(1)      not null            comment '是否并发',
    is_update_data       varchar(1)      not null            comment '是否更新数据',
    requests_recovery    varchar(1)      not null            comment '是否接受恢复执行',
    job_data             blob            null                comment '存放持久化job对象',
    primary key (sched_name, job_name, job_group)
) engine=innodb comment = '任务详细信息表';

-- ----------------------------
-- 2、 存储已配置的 Trigger 的信息
-- ----------------------------
create table QRTZ_TRIGGERS (
    sched_name           varchar(120)    not null            comment '调度名称',
    trigger_name         varchar(200)    not null            comment '触发器的名字',
    trigger_group        varchar(200)    not null            comment '触发器所属组的名字',
    job_name             varchar(200)    not null            comment 'qrtz_job_details表job_name的外键',
    job_group            varchar(200)    not null            comment 'qrtz_job_details表job_group的外键',
    description          varchar(250)    null                comment '相关介绍',
    next_fire_time       bigint(13)      null                comment '上一次触发时间（毫秒）',
    prev_fire_time       bigint(13)      null                comment '下一次触发时间（默认为-1表示不触发）',
    priority             integer         null                comment '优先级',
    trigger_state        varchar(16)     not null            comment '触发器状态',
    trigger_type         varchar(8)      not null            comment '触发器的类型',
    start_time           bigint(13)      not null            comment '开始时间',
    end_time             bigint(13)      null                comment '结束时间',
    calendar_name        varchar(200)    null                comment '日程表名称',
    misfire_instr        smallint(2)     null                comment '补偿执行的策略',
    job_data             blob            null                comment '存放持久化job对象',
    primary key (sched_name, trigger_name, trigger_group),
    foreign key (sched_name, job_name, job_group) references QRTZ_JOB_DETAILS(sched_name, job_name, job_group)
) engine=innodb comment = '触发器详细信息表';

-- ----------------------------
-- 3、 存储简单的 Trigger，包括重复次数，间隔，以及已触发的次数
-- ----------------------------
create table QRTZ_SIMPLE_TRIGGERS (
    sched_name           varchar(120)    not null            comment '调度名称',
    trigger_name         varchar(200)    not null            comment 'qrtz_triggers表trigger_name的外键',
    trigger_group        varchar(200)    not null            comment 'qrtz_triggers表trigger_group的外键',
    repeat_count         bigint(7)       not null            comment '重复的次数统计',
    repeat_interval      bigint(12)      not null            comment '重复的间隔时间',
    times_triggered      bigint(10)      not null            comment '已经触发的次数',
    primary key (sched_name, trigger_name, trigger_group),
    foreign key (sched_name, trigger_name, trigger_group) references QRTZ_TRIGGERS(sched_name, trigger_name, trigger_group)
) engine=innodb comment = '简单触发器的信息表';

-- ----------------------------
-- 4、 存储 Cron Trigger，包括 Cron 表达式和时区信息
-- ---------------------------- 
create table QRTZ_CRON_TRIGGERS (
    sched_name           varchar(120)    not null            comment '调度名称',
    trigger_name         varchar(200)    not null            comment 'qrtz_triggers表trigger_name的外键',
    trigger_group        varchar(200)    not null            comment 'qrtz_triggers表trigger_group的外键',
    cron_expression      varchar(200)    not null            comment 'cron表达式',
    time_zone_id         varchar(80)                         comment '时区',
    primary key (sched_name, trigger_name, trigger_group),
    foreign key (sched_name, trigger_name, trigger_group) references QRTZ_TRIGGERS(sched_name, trigger_name, trigger_group)
) engine=innodb comment = 'Cron类型的触发器表';

-- ----------------------------
-- 5、 Trigger 作为 Blob 类型存储(用于 Quartz 用户用 JDBC 创建他们自己定制的 Trigger 类型，JobStore 并不知道如何存储实例的时候)
-- ---------------------------- 
create table QRTZ_BLOB_TRIGGERS (
    sched_name           varchar(120)    not null            comment '调度名称',
    trigger_name         varchar(200)    not null            comment 'qrtz_triggers表trigger_name的外键',
    trigger_group        varchar(200)    not null            comment 'qrtz_triggers表trigger_group的外键',
    blob_data            blob            null                comment '存放持久化Trigger对象',
    primary key (sched_name, trigger_name, trigger_group),
    foreign key (sched_name, trigger_name, trigger_group) references QRTZ_TRIGGERS(sched_name, trigger_name, trigger_group)
) engine=innodb comment = 'Blob类型的触发器表';

-- ----------------------------
-- 6、 以 Blob 类型存储存放日历信息， quartz可配置一个日历来指定一个时间范围
-- ---------------------------- 
create table QRTZ_CALENDARS (
    sched_name           varchar(120)    not null            comment '调度名称',
    calendar_name        varchar(200)    not null            comment '日历名称',
    calendar             blob            not null            comment '存放持久化calendar对象',
    primary key (sched_name, calendar_name)
) engine=innodb comment = '日历信息表';

-- ----------------------------
-- 7、 存储已暂停的 Trigger 组的信息
-- ---------------------------- 
create table QRTZ_PAUSED_TRIGGER_GRPS (
    sched_name           varchar(120)    not null            comment '调度名称',
    trigger_group        varchar(200)    not null            comment 'qrtz_triggers表trigger_group的外键',
    primary key (sched_name, trigger_group)
) engine=innodb comment = '暂停的触发器表';

-- ----------------------------
-- 8、 存储与已触发的 Trigger 相关的状态信息，以及相联 Job 的执行信息
-- ---------------------------- 
create table QRTZ_FIRED_TRIGGERS (
    sched_name           varchar(120)    not null            comment '调度名称',
    entry_id             varchar(95)     not null            comment '调度器实例id',
    trigger_name         varchar(200)    not null            comment 'qrtz_triggers表trigger_name的外键',
    trigger_group        varchar(200)    not null            comment 'qrtz_triggers表trigger_group的外键',
    instance_name        varchar(200)    not null            comment '调度器实例名',
    fired_time           bigint(13)      not null            comment '触发的时间',
    sched_time           bigint(13)      not null            comment '定时器制定的时间',
    priority             integer         not null            comment '优先级',
    state                varchar(16)     not null            comment '状态',
    job_name             varchar(200)    null                comment '任务名称',
    job_group            varchar(200)    null                comment '任务组名',
    is_nonconcurrent     varchar(1)      null                comment '是否并发',
    requests_recovery    varchar(1)      null                comment '是否接受恢复执行',
    primary key (sched_name, entry_id)
) engine=innodb comment = '已触发的触发器表';

-- ----------------------------
-- 9、 存储少量的有关 Scheduler 的状态信息，假如是用于集群中，可以看到其他的 Scheduler 实例
-- ---------------------------- 
create table QRTZ_SCHEDULER_STATE (
    sched_name           varchar(120)    not null            comment '调度名称',
    instance_name        varchar(200)    not null            comment '实例名称',
    last_checkin_time    bigint(13)      not null            comment '上次检查时间',
    checkin_interval     bigint(13)      not null            comment '检查间隔时间',
    primary key (sched_name, instance_name)
) engine=innodb comment = '调度器状态表';

-- ----------------------------
-- 10、 存储程序的悲观锁的信息(假如使用了悲观锁)
-- ---------------------------- 
create table QRTZ_LOCKS (
    sched_name           varchar(120)    not null            comment '调度名称',
    lock_name            varchar(40)     not null            comment '悲观锁名称',
    primary key (sched_name, lock_name)
) engine=innodb comment = '存储的悲观锁信息表';

-- ----------------------------
-- 11、 Quartz集群实现同步机制的行锁表
-- ---------------------------- 
create table QRTZ_SIMPROP_TRIGGERS (
    sched_name           varchar(120)    not null            comment '调度名称',
    trigger_name         varchar(200)    not null            comment 'qrtz_triggers表trigger_name的外键',
    trigger_group        varchar(200)    not null            comment 'qrtz_triggers表trigger_group的外键',
    str_prop_1           varchar(512)    null                comment 'String类型的trigger的第一个参数',
    str_prop_2           varchar(512)    null                comment 'String类型的trigger的第二个参数',
    str_prop_3           varchar(512)    null                comment 'String类型的trigger的第三个参数',
    int_prop_1           int             null                comment 'int类型的trigger的第一个参数',
    int_prop_2           int             null                comment 'int类型的trigger的第二个参数',
    long_prop_1          bigint          null                comment 'long类型的trigger的第一个参数',
    long_prop_2          bigint          null                comment 'long类型的trigger的第二个参数',
    dec_prop_1           numeric(13,4)   null                comment 'decimal类型的trigger的第一个参数',
    dec_prop_2           numeric(13,4)   null                comment 'decimal类型的trigger的第二个参数',
    bool_prop_1          varchar(1)      null                comment 'Boolean类型的trigger的第一个参数',
    bool_prop_2          varchar(1)      null                comment 'Boolean类型的trigger的第二个参数',
    primary key (sched_name, trigger_name, trigger_group),
    foreign key (sched_name, trigger_name, trigger_group) references QRTZ_TRIGGERS(sched_name, trigger_name, trigger_group)
) engine=innodb comment = '同步机制的行锁表';

commit;
-- END SOURCE: quartz.sql

-- ============================================================================
-- BEGIN SOURCE: 03_workorder_core_schema.sql
-- SHA256: f4cb4a6fab5ddb7ebe5fde11e071b335998a29ef201f17caee353faf1de29811
-- ============================================================================
-- 医院后勤工单系统 M0/M1 核心表（MySQL 8.0）
-- 增量脚本：仅创建不存在的表，不覆盖既有业务数据。
-- 业务表只保留逻辑外键，由服务层保证跨表一致性，并为常用关联字段建立索引。

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS wo_category (
  id                    BIGINT       NOT NULL AUTO_INCREMENT COMMENT '分类ID',
  parent_id             BIGINT       NOT NULL DEFAULT 0 COMMENT '父分类ID，0表示根分类',
  category_code         VARCHAR(32)  NOT NULL COMMENT '分类编码',
  category_name         VARCHAR(64)  NOT NULL COMMENT '分类名称',
  manager_dept_id       BIGINT       NULL COMMENT '默认负责部门ID，逻辑关联sys_dept.dept_id',
  default_sla_rule_id   BIGINT       NULL COMMENT '默认SLA规则ID，逻辑关联wo_sla_rule.id',
  order_num             INT          NOT NULL DEFAULT 0 COMMENT '显示顺序',
  status                CHAR(1)      NOT NULL DEFAULT '0' COMMENT '状态：0正常 1停用',
  create_by             VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '创建者',
  create_time           DATETIME     NULL COMMENT '创建时间',
  update_by             VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '更新者',
  update_time           DATETIME     NULL COMMENT '更新时间',
  remark                VARCHAR(500) NULL COMMENT '备注',
  del_flag              CHAR(1)      NOT NULL DEFAULT '0' COMMENT '删除标志：0正常 2删除',
  PRIMARY KEY (id),
  UNIQUE KEY uk_wo_category_code (category_code),
  KEY idx_wo_category_parent (parent_id, status, del_flag),
  KEY idx_wo_category_manager_dept (manager_dept_id, status, del_flag),
  KEY idx_wo_category_default_sla (default_sla_rule_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='工单业务分类';

CREATE TABLE IF NOT EXISTS wo_sla_rule (
  id                    BIGINT       NOT NULL AUTO_INCREMENT COMMENT '规则ID',
  rule_code             VARCHAR(32)  NOT NULL COMMENT '规则编码',
  rule_name             VARCHAR(64)  NOT NULL COMMENT '规则名称',
  category_id           BIGINT       NULL COMMENT '适用分类ID，空表示全局兜底',
  urgency_level         TINYINT      NOT NULL COMMENT '紧急程度：1一般 2紧急 3特急',
  priority              INT          NOT NULL COMMENT '匹配优先级，数值越大越优先',
  effective_from        DATETIME     NOT NULL COMMENT '生效时间（含）',
  effective_to          DATETIME     NULL COMMENT '失效时间（不含），空表示长期有效',
  response_minutes      INT          NOT NULL COMMENT '接单/响应时限（分钟）',
  arrival_minutes       INT          NULL COMMENT '到场时限（分钟）',
  finish_minutes        INT          NULL COMMENT '完工时限（分钟）',
  reminder_before_min   INT          NOT NULL DEFAULT 15 COMMENT '到期前提醒分钟数',
  allow_extension       CHAR(1)      NOT NULL DEFAULT '1' COMMENT '是否允许延期：0否 1是',
  status                CHAR(1)      NOT NULL DEFAULT '0' COMMENT '状态：0正常 1停用',
  create_by             VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '创建者',
  create_time           DATETIME     NULL COMMENT '创建时间',
  update_by             VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '更新者',
  update_time           DATETIME     NULL COMMENT '更新时间',
  remark                VARCHAR(500) NULL COMMENT '备注',
  del_flag              CHAR(1)      NOT NULL DEFAULT '0' COMMENT '删除标志：0正常 2删除',
  PRIMARY KEY (id),
  UNIQUE KEY uk_wo_sla_rule_code (rule_code),
  KEY idx_wo_sla_match (urgency_level, category_id, status, del_flag, priority, effective_from, effective_to),
  KEY idx_wo_sla_category (category_id),
  CONSTRAINT chk_wo_sla_urgency CHECK (urgency_level BETWEEN 1 AND 3),
  CONSTRAINT chk_wo_sla_priority CHECK (priority >= 0),
  CONSTRAINT chk_wo_sla_response CHECK (response_minutes > 0),
  CONSTRAINT chk_wo_sla_arrival CHECK (arrival_minutes IS NULL OR arrival_minutes > 0),
  CONSTRAINT chk_wo_sla_finish CHECK (finish_minutes IS NULL OR finish_minutes > 0),
  CONSTRAINT chk_wo_sla_effective_period CHECK (effective_to IS NULL OR effective_to > effective_from)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='工单SLA规则';

CREATE TABLE IF NOT EXISTS wo_order (
  id                    BIGINT        NOT NULL AUTO_INCREMENT COMMENT '工单ID',
  order_no              VARCHAR(32)   NOT NULL COMMENT '工单编号',
  title                 VARCHAR(128)  NOT NULL COMMENT '工单标题',
  category_id           BIGINT        NOT NULL COMMENT '分类ID，逻辑关联wo_category.id',
  category_code         VARCHAR(32)   NOT NULL COMMENT '分类编码快照',
  category_name         VARCHAR(64)   NOT NULL COMMENT '分类名称快照',
  source_type           TINYINT       NOT NULL DEFAULT 1 COMMENT '来源：1手机端 2PC端 3接口导入',
  applicant_id          BIGINT        NOT NULL COMMENT '申请人用户ID，逻辑关联sys_user.user_id',
  applicant_name        VARCHAR(64)   NOT NULL COMMENT '申请人姓名快照',
  applicant_phone       VARCHAR(32)   NOT NULL COMMENT '申请人联系电话',
  applicant_dept_id     BIGINT        NULL COMMENT '申请科室ID，逻辑关联sys_dept.dept_id',
  applicant_dept_name   VARCHAR(64)   NULL COMMENT '申请科室名称快照',
  location              VARCHAR(255)  NOT NULL COMMENT '故障位置',
  urgency_level         TINYINT       NOT NULL COMMENT '紧急程度：1一般 2紧急 3特急',
  impact_scope          TINYINT       NOT NULL COMMENT '影响范围：1个人 2科室 3多科室 4全院',
  description           VARCHAR(1000) NOT NULL COMMENT '故障现象描述',
  possible_cause        VARCHAR(1000) NULL COMMENT '可能原因/补充说明',
  status                VARCHAR(32)   NOT NULL COMMENT '业务主状态',
  current_assignee_id   BIGINT        NULL COMMENT '当前维修工程师ID，逻辑关联sys_user.user_id',
  current_assignee_name VARCHAR(64)    NULL COMMENT '当前维修工程师姓名快照',
  sla_rule_id           BIGINT        NULL COMMENT '命中的SLA规则ID，逻辑关联wo_sla_rule.id',
  response_deadline     DATETIME      NULL COMMENT '响应截止时间',
  arrival_deadline      DATETIME      NULL COMMENT '到场截止时间',
  finish_deadline       DATETIME      NULL COMMENT '完工截止时间',
  submitted_at          DATETIME      NULL COMMENT '提交时间',
  assigned_at           DATETIME      NULL COMMENT '最近分派时间',
  accepted_at           DATETIME      NULL COMMENT '接单时间',
  arrived_at            DATETIME      NULL COMMENT '到场时间',
  processing_at         DATETIME      NULL COMMENT '开始处理时间',
  finished_at           DATETIME      NULL COMMENT '工程师提交完工时间',
  confirmed_at          DATETIME      NULL COMMENT '申请人确认时间',
  closed_at             DATETIME      NULL COMMENT '关闭时间',
  overdue_flag          CHAR(1)       NOT NULL DEFAULT '0' COMMENT '是否存在任一SLA超期：0否 1是',
  warning_flag          CHAR(1)       NOT NULL DEFAULT '0' COMMENT '是否处于SLA预警：0否 1是',
  delay_pending_flag    CHAR(1)       NOT NULL DEFAULT '0' COMMENT '是否存在待审批延期：0否 1是',
  response_overdue      CHAR(1)       NOT NULL DEFAULT '0' COMMENT '响应是否超期：0否 1是',
  arrival_overdue       CHAR(1)       NOT NULL DEFAULT '0' COMMENT '到场是否超期：0否 1是',
  finish_overdue        CHAR(1)       NOT NULL DEFAULT '0' COMMENT '完工是否超期：0否 1是',
  extension_deadline    DATETIME      NULL COMMENT '审批后的延期截止时间',
  version               INT           NOT NULL DEFAULT 0 COMMENT '乐观锁版本号',
  create_by             VARCHAR(64)   NOT NULL DEFAULT '' COMMENT '创建者',
  create_time           DATETIME      NULL COMMENT '创建时间',
  update_by             VARCHAR(64)   NOT NULL DEFAULT '' COMMENT '更新者',
  update_time           DATETIME      NULL COMMENT '更新时间',
  remark                VARCHAR(500)  NULL COMMENT '备注',
  del_flag              CHAR(1)       NOT NULL DEFAULT '0' COMMENT '删除标志：0正常 2删除',
  PRIMARY KEY (id),
  UNIQUE KEY uk_wo_order_no (order_no),
  KEY idx_wo_order_category (category_id, status, create_time),
  KEY idx_wo_order_sla_rule (sla_rule_id),
  KEY idx_wo_order_applicant (applicant_id, status, create_time),
  KEY idx_wo_order_assignee (current_assignee_id, status, create_time),
  KEY idx_wo_order_status (status, urgency_level, create_time),
  KEY idx_wo_order_response_deadline (status, response_overdue, response_deadline),
  KEY idx_wo_order_arrival_deadline (status, arrival_overdue, arrival_deadline),
  KEY idx_wo_order_finish_deadline (status, finish_overdue, finish_deadline),
  KEY idx_wo_order_warning (warning_flag, status, finish_deadline),
  KEY idx_wo_order_dept (applicant_dept_id, create_time),
  CONSTRAINT chk_wo_order_source CHECK (source_type BETWEEN 1 AND 3),
  CONSTRAINT chk_wo_order_urgency CHECK (urgency_level BETWEEN 1 AND 3),
  CONSTRAINT chk_wo_order_impact CHECK (impact_scope BETWEEN 1 AND 4)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='工单主表';

CREATE TABLE IF NOT EXISTS wo_attachment (
  id                    BIGINT       NOT NULL AUTO_INCREMENT COMMENT '附件ID',
  order_id              BIGINT       NULL COMMENT '工单ID，上传暂存时为空，提交后逻辑关联wo_order.id',
  biz_stage             VARCHAR(32)  NOT NULL COMMENT '附件阶段：SUBMIT/ARRIVAL/PROCESS/FINISH/EVALUATION',
  biz_ref_id            BIGINT       NULL COMMENT '关联业务记录ID',
  file_name             VARCHAR(255) NOT NULL COMMENT '原文件名',
  object_key            VARCHAR(512) NOT NULL COMMENT '对象存储键，不对外暴露公开URL',
  storage_provider      VARCHAR(32)  NOT NULL COMMENT '存储提供方：LOCAL/MINIO/OSS/COS等',
  file_hash             VARCHAR(128) NULL COMMENT '文件内容哈希',
  file_type             VARCHAR(128) NULL COMMENT 'MIME类型',
  file_size             BIGINT       NULL COMMENT '文件大小（字节）',
  uploader_id           BIGINT       NOT NULL COMMENT '上传人ID，逻辑关联sys_user.user_id',
  uploader_name         VARCHAR(64)  NULL COMMENT '上传人姓名快照',
  create_time           DATETIME     NOT NULL COMMENT '上传时间',
  del_flag              CHAR(1)      NOT NULL DEFAULT '0' COMMENT '删除标志：0正常 2删除',
  PRIMARY KEY (id),
  UNIQUE KEY uk_wo_attachment_object_key (object_key),
  KEY idx_wo_attachment_order (order_id, biz_stage, create_time),
  KEY idx_wo_attachment_biz_ref (biz_ref_id),
  KEY idx_wo_attachment_uploader (uploader_id, create_time),
  KEY idx_wo_attachment_hash (file_hash)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='工单附件';

CREATE TABLE IF NOT EXISTS wo_assignment (
  id                    BIGINT       NOT NULL AUTO_INCREMENT COMMENT '分派记录ID',
  order_id              BIGINT       NOT NULL COMMENT '工单ID，逻辑关联wo_order.id',
  engineer_id           BIGINT       NOT NULL COMMENT '维修工程师ID，逻辑关联sys_user.user_id',
  engineer_name         VARCHAR(64)  NOT NULL COMMENT '维修工程师姓名快照',
  engineer_dept_id      BIGINT       NULL COMMENT '维修部门ID，逻辑关联sys_dept.dept_id',
  assigned_by           BIGINT       NOT NULL COMMENT '分派人ID，逻辑关联sys_user.user_id',
  assigned_by_name      VARCHAR(64)  NOT NULL COMMENT '分派人姓名快照',
  assigned_at           DATETIME     NOT NULL COMMENT '分派时间',
  response_minutes      INT          NOT NULL COMMENT '本次响应时限（分钟）',
  response_deadline     DATETIME     NOT NULL COMMENT '本次响应截止时间',
  assignment_status     VARCHAR(24)  NOT NULL COMMENT 'ACTIVE/ACCEPTED/REASSIGNED/RETURNED/CANCELLED',
  accepted_at           DATETIME     NULL COMMENT '接单时间',
  ended_at              DATETIME     NULL COMMENT '本次分派结束时间',
  return_reason         VARCHAR(500) NULL COMMENT '退回/转派原因',
  create_time           DATETIME     NOT NULL COMMENT '创建时间',
  PRIMARY KEY (id),
  KEY idx_wo_assignment_order (order_id, assigned_at),
  KEY idx_wo_assignment_engineer (engineer_id, assignment_status, assigned_at),
  KEY idx_wo_assignment_engineer_dept (engineer_dept_id, assigned_at),
  KEY idx_wo_assignment_operator (assigned_by, assigned_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='工单分派历史';

CREATE TABLE IF NOT EXISTS wo_action_log (
  id                    BIGINT        NOT NULL AUTO_INCREMENT COMMENT '操作日志ID',
  order_id              BIGINT        NOT NULL COMMENT '工单ID，逻辑关联wo_order.id',
  action_type           VARCHAR(32)   NOT NULL COMMENT '动作类型',
  from_status           VARCHAR(32)   NULL COMMENT '原状态',
  to_status             VARCHAR(32)   NULL COMMENT '目标状态',
  operator_id           BIGINT        NOT NULL COMMENT '操作人ID，逻辑关联sys_user.user_id',
  operator_name         VARCHAR(64)   NOT NULL COMMENT '操作人姓名快照',
  operator_role         VARCHAR(32)   NOT NULL COMMENT '操作角色快照',
  action_content        VARCHAR(1000) NULL COMMENT '操作说明',
  ext_json              JSON          NULL COMMENT '扩展快照',
  idempotency_key       VARCHAR(64)   NOT NULL COMMENT '动作幂等键',
  action_time           DATETIME      NOT NULL COMMENT '操作时间',
  PRIMARY KEY (id),
  UNIQUE KEY uk_wo_action_idempotency (operator_id, action_type, idempotency_key),
  KEY idx_wo_action_order (order_id, action_time),
  KEY idx_wo_action_operator (operator_id, action_time),
  KEY idx_wo_action_type (action_type, action_time)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='工单流转审计日志';

CREATE TABLE IF NOT EXISTS wo_process_record (
  id                    BIGINT        NOT NULL AUTO_INCREMENT COMMENT '处理记录ID',
  order_id              BIGINT        NOT NULL COMMENT '工单ID，逻辑关联wo_order.id',
  record_stage          VARCHAR(24)   NOT NULL COMMENT 'ARRIVAL/ASSESSMENT/PROGRESS/FINISH',
  engineer_id           BIGINT        NOT NULL COMMENT '工程师ID，逻辑关联sys_user.user_id',
  engineer_name         VARCHAR(64)   NOT NULL COMMENT '工程师姓名快照',
  requires_parts        CHAR(1)       NULL COMMENT '是否需要零部件：0否 1是',
  parts_description     VARCHAR(500)  NULL COMMENT '零部件说明',
  assessed_hours        DECIMAL(8,2)  NULL COMMENT '评估工时',
  assessed_urgency      TINYINT       NULL COMMENT '现场评估紧急程度',
  assessed_scope        TINYINT       NULL COMMENT '现场评估影响范围',
  requires_extension    CHAR(1)       NULL COMMENT '是否需要延期：0否 1是',
  content               VARCHAR(2000) NOT NULL COMMENT '现场说明/处理过程/完工说明',
  occurred_at           DATETIME      NOT NULL COMMENT '业务发生时间',
  create_time           DATETIME      NOT NULL COMMENT '创建时间',
  PRIMARY KEY (id),
  KEY idx_wo_process_order (order_id, record_stage, occurred_at),
  KEY idx_wo_process_engineer (engineer_id, occurred_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='维修处理记录';

CREATE TABLE IF NOT EXISTS wo_evaluation (
  id                    BIGINT       NOT NULL AUTO_INCREMENT COMMENT '评价ID',
  order_id              BIGINT       NOT NULL COMMENT '工单ID，逻辑关联wo_order.id',
  evaluator_id          BIGINT       NOT NULL COMMENT '评价人ID，逻辑关联sys_user.user_id',
  overall_score         TINYINT      NOT NULL COMMENT '总体评分1-5',
  response_score        TINYINT      NULL COMMENT '响应速度评分1-5',
  quality_score         TINYINT      NULL COMMENT '维修质量评分1-5',
  attitude_score        TINYINT      NULL COMMENT '服务态度评分1-5',
  evaluation_content    VARCHAR(500) NULL COMMENT '评价内容',
  evaluated_at          DATETIME     NOT NULL COMMENT '评价时间',
  create_time           DATETIME     NOT NULL COMMENT '创建时间',
  PRIMARY KEY (id),
  UNIQUE KEY uk_wo_evaluation_order (order_id),
  KEY idx_wo_evaluation_user (evaluator_id, evaluated_at),
  CONSTRAINT chk_wo_evaluation_overall CHECK (overall_score BETWEEN 1 AND 5),
  CONSTRAINT chk_wo_evaluation_response CHECK (response_score IS NULL OR response_score BETWEEN 1 AND 5),
  CONSTRAINT chk_wo_evaluation_quality CHECK (quality_score IS NULL OR quality_score BETWEEN 1 AND 5),
  CONSTRAINT chk_wo_evaluation_attitude CHECK (attitude_score IS NULL OR attitude_score BETWEEN 1 AND 5)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='工单服务评价';

CREATE TABLE IF NOT EXISTS wo_engineer_status (
  id                    BIGINT       NOT NULL AUTO_INCREMENT COMMENT '状态记录ID',
  engineer_id           BIGINT       NOT NULL COMMENT '工程师用户ID，逻辑关联sys_user.user_id',
  engineer_name         VARCHAR(64)  NOT NULL COMMENT '工程师姓名快照',
  engineer_dept_id      BIGINT       NULL COMMENT '所属维修部门，逻辑关联sys_dept.dept_id',
  duty_status           VARCHAR(16)  NOT NULL COMMENT '值班状态：OFF_DUTY/ON_DUTY',
  work_status           VARCHAR(16)  NOT NULL COMMENT '工作状态：AVAILABLE/WORKING/BUSY',
  current_order_id      BIGINT       NULL COMMENT '当前主工单ID，逻辑关联wo_order.id',
  active_order_count    INT          NOT NULL DEFAULT 0 COMMENT '进行中工单数',
  overdue_order_count   INT          NOT NULL DEFAULT 0 COMMENT '超期工单数',
  status_source         VARCHAR(16)  NOT NULL DEFAULT 'AUTO' COMMENT '状态来源：AUTO/MANUAL',
  last_changed_at       DATETIME     NOT NULL COMMENT '最近状态变化时间',
  last_heartbeat_at     DATETIME     NULL COMMENT '客户端最近心跳时间，空表示从未上报',
  update_time           DATETIME     NOT NULL COMMENT '更新时间',
  PRIMARY KEY (id),
  UNIQUE KEY uk_wo_engineer_status_user (engineer_id),
  KEY idx_wo_engineer_status (duty_status, work_status, overdue_order_count),
  KEY idx_wo_engineer_dept (engineer_dept_id, duty_status, work_status),
  KEY idx_wo_engineer_current_order (current_order_id),
  KEY idx_wo_engineer_heartbeat (last_heartbeat_at),
  CONSTRAINT chk_wo_engineer_active_count CHECK (active_order_count >= 0),
  CONSTRAINT chk_wo_engineer_overdue_count CHECK (overdue_order_count >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='维修工程师状态快照';
-- END SOURCE: 03_workorder_core_schema.sql

-- ============================================================================
-- BEGIN SOURCE: 04_workorder_dict.sql
-- SHA256: 9be0b95b6ea0130b33aad3912f088997868f8e5e4fb0ff48d5b1f7e5a7d7edc0
-- ============================================================================
-- 工单稳定字典初始化（依赖 01-ruoyi.sql）
-- 使用业务键判重，不依赖自增ID，可重复执行。

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

INSERT INTO sys_dict_type
  (dict_name, dict_type, status, create_by, create_time, update_by, update_time, remark)
SELECT '工单状态', 'wo_order_status', '0', 'admin', NOW(), '', NULL, '工单主状态机稳定字典'
WHERE NOT EXISTS (SELECT 1 FROM sys_dict_type WHERE dict_type = 'wo_order_status');

INSERT INTO sys_dict_type
  (dict_name, dict_type, status, create_by, create_time, update_by, update_time, remark)
SELECT '工单紧急程度', 'wo_urgency_level', '0', 'admin', NOW(), '', NULL, '工单紧急程度稳定字典'
WHERE NOT EXISTS (SELECT 1 FROM sys_dict_type WHERE dict_type = 'wo_urgency_level');

INSERT INTO sys_dict_type
  (dict_name, dict_type, status, create_by, create_time, update_by, update_time, remark)
SELECT '工单影响范围', 'wo_impact_scope', '0', 'admin', NOW(), '', NULL, '工单影响范围稳定字典'
WHERE NOT EXISTS (SELECT 1 FROM sys_dict_type WHERE dict_type = 'wo_impact_scope');

INSERT INTO sys_dict_type
  (dict_name, dict_type, status, create_by, create_time, update_by, update_time, remark)
SELECT '工单来源', 'wo_source_type', '0', 'admin', NOW(), '', NULL, '工单来源稳定字典'
WHERE NOT EXISTS (SELECT 1 FROM sys_dict_type WHERE dict_type = 'wo_source_type');

INSERT INTO sys_dict_type
  (dict_name, dict_type, status, create_by, create_time, update_by, update_time, remark)
SELECT '派单状态', 'wo_assignment_status', '0', 'admin', NOW(), '', NULL, '派单历史状态稳定字典'
WHERE NOT EXISTS (SELECT 1 FROM sys_dict_type WHERE dict_type = 'wo_assignment_status');

INSERT INTO sys_dict_type
  (dict_name, dict_type, status, create_by, create_time, update_by, update_time, remark)
SELECT '处理阶段', 'wo_process_stage', '0', 'admin', NOW(), '', NULL, '维修处理阶段稳定字典'
WHERE NOT EXISTS (SELECT 1 FROM sys_dict_type WHERE dict_type = 'wo_process_stage');

INSERT INTO sys_dict_type
  (dict_name, dict_type, status, create_by, create_time, update_by, update_time, remark)
SELECT '维修人员状态', 'wo_engineer_status', '0', 'admin', NOW(), '', NULL, '人员调度展示状态稳定字典'
WHERE NOT EXISTS (SELECT 1 FROM sys_dict_type WHERE dict_type = 'wo_engineer_status');

INSERT INTO sys_dict_type
  (dict_name, dict_type, status, create_by, create_time, update_by, update_time, remark)
SELECT '工单附件阶段', 'wo_attachment_stage', '0', 'admin', NOW(), '', NULL, '附件所属业务阶段稳定字典'
WHERE NOT EXISTS (SELECT 1 FROM sys_dict_type WHERE dict_type = 'wo_attachment_stage');

INSERT INTO sys_dict_data
  (dict_sort, dict_label, dict_value, dict_type, css_class, list_class,
   is_default, status, create_by, create_time, update_by, update_time, remark)
SELECT seed.dict_sort, seed.dict_label, seed.dict_value, seed.dict_type,
       seed.css_class, seed.list_class, seed.is_default, '0',
       'admin', NOW(), '', NULL, seed.remark
FROM (
  SELECT 1 dict_sort, '草稿' dict_label, 'DRAFT' dict_value, 'wo_order_status' dict_type, '' css_class, 'info' list_class, 'N' is_default, '未提交的内部状态' remark
  UNION ALL SELECT 2, '待派单', 'WAIT_ASSIGN', 'wo_order_status', '', 'warning', 'N', '已提交，等待调度派单'
  UNION ALL SELECT 3, '待接单', 'WAIT_ACCEPT', 'wo_order_status', '', 'warning', 'N', '已派单，等待维修人员接单'
  UNION ALL SELECT 4, '已接单', 'ACCEPTED', 'wo_order_status', '', 'primary', 'N', '已接单，等待到场'
  UNION ALL SELECT 5, '处理中', 'PROCESSING', 'wo_order_status', '', 'primary', 'N', '维修处理中'
  UNION ALL SELECT 6, '待确认', 'WAIT_CONFIRM', 'wo_order_status', '', 'warning', 'N', '已完工，等待报修人确认'
  UNION ALL SELECT 7, '已完成', 'COMPLETED', 'wo_order_status', '', 'success', 'N', '已确认，等待评价'
  UNION ALL SELECT 8, '已关闭', 'CLOSED', 'wo_order_status', '', 'info', 'N', '已评价并关闭'
  UNION ALL SELECT 9, '已取消', 'CANCELLED', 'wo_order_status', '', 'danger', 'N', '派单前取消'

  UNION ALL SELECT 1, '一般', '1', 'wo_urgency_level', '', 'info', 'Y', '一般工单'
  UNION ALL SELECT 2, '紧急', '2', 'wo_urgency_level', '', 'warning', 'N', '紧急工单'
  UNION ALL SELECT 3, '特急', '3', 'wo_urgency_level', '', 'danger', 'N', '特急工单'

  UNION ALL SELECT 1, '个人', '1', 'wo_impact_scope', '', 'info', 'Y', '影响个人'
  UNION ALL SELECT 2, '科室', '2', 'wo_impact_scope', '', 'primary', 'N', '影响单个科室'
  UNION ALL SELECT 3, '多科室', '3', 'wo_impact_scope', '', 'warning', 'N', '影响多个科室'
  UNION ALL SELECT 4, '全院', '4', 'wo_impact_scope', '', 'danger', 'N', '影响全院'

  UNION ALL SELECT 1, '微信小程序', '1', 'wo_source_type', '', 'primary', 'Y', '由微信小程序提交'
  UNION ALL SELECT 2, 'PC端', '2', 'wo_source_type', '', 'info', 'N', '由PC管理端提交'
  UNION ALL SELECT 3, '接口导入', '3', 'wo_source_type', '', 'warning', 'N', '由外部接口导入'

  UNION ALL SELECT 1, '生效中', 'ACTIVE', 'wo_assignment_status', '', 'primary', 'N', '当前生效的派单'
  UNION ALL SELECT 2, '已接单', 'ACCEPTED', 'wo_assignment_status', '', 'success', 'N', '维修人员已接单'
  UNION ALL SELECT 3, '已改派', 'REASSIGNED', 'wo_assignment_status', '', 'warning', 'N', '该派单已被改派替代'
  UNION ALL SELECT 4, '已退回', 'RETURNED', 'wo_assignment_status', '', 'danger', 'N', '该派单已退回'
  UNION ALL SELECT 5, '已取消', 'CANCELLED', 'wo_assignment_status', '', 'info', 'N', '该派单已取消'

  UNION ALL SELECT 1, '到场', 'ARRIVAL', 'wo_process_stage', '', 'primary', 'N', '到场确认记录'
  UNION ALL SELECT 2, '故障评估', 'ASSESSMENT', 'wo_process_stage', '', 'warning', 'N', '故障评估记录'
  UNION ALL SELECT 3, '处理进度', 'PROGRESS', 'wo_process_stage', '', 'primary', 'N', '处理进度记录'
  UNION ALL SELECT 4, '完工', 'FINISH', 'wo_process_stage', '', 'success', 'N', '完工记录'

  UNION ALL SELECT 1, '未值班', 'OFF_DUTY', 'wo_engineer_status', '', 'info', 'N', '当前未值班'
  UNION ALL SELECT 2, '空闲', 'AVAILABLE', 'wo_engineer_status', '', 'success', 'N', '值班且可接单'
  UNION ALL SELECT 3, '工作中', 'WORKING', 'wo_engineer_status', '', 'primary', 'N', '正在处理工单'
  UNION ALL SELECT 4, '繁忙', 'BUSY', 'wo_engineer_status', '', 'warning', 'N', '负载较高'
  UNION ALL SELECT 5, '离线', 'OFFLINE', 'wo_engineer_status', '', 'danger', 'N', '心跳超时或不可用'

  UNION ALL SELECT 1, '报修提交', 'SUBMIT', 'wo_attachment_stage', '', 'info', 'N', '报修提交附件'
  UNION ALL SELECT 2, '到场确认', 'ARRIVAL', 'wo_attachment_stage', '', 'primary', 'N', '到场证据附件'
  UNION ALL SELECT 3, '处理过程', 'PROCESS', 'wo_attachment_stage', '', 'primary', 'N', '处理过程附件'
  UNION ALL SELECT 4, '完工提交', 'FINISH', 'wo_attachment_stage', '', 'success', 'N', '完工证据附件'
  UNION ALL SELECT 5, '服务评价', 'EVALUATION', 'wo_attachment_stage', '', 'info', 'N', '评价附件'
) seed
WHERE NOT EXISTS (
  SELECT 1
  FROM sys_dict_data existing
  WHERE existing.dict_type = seed.dict_type
    AND existing.dict_value = seed.dict_value
);
-- END SOURCE: 04_workorder_dict.sql

-- ============================================================================
-- BEGIN SOURCE: 05_workorder_menu.sql
-- SHA256: 268e89f2f30a3938fbdef56c1dc4eef34ce6e3d84658f8fd21d212b089a7cee0
-- ============================================================================
-- 工单菜单与按钮权限初始化（依赖 01-ruoyi.sql）
-- C 类型页面菜单暂设为停用，前端页面落地后再显式启用，避免返回不存在的组件。

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

INSERT INTO sys_menu
  (menu_name, parent_id, order_num, path, component, query, route_name,
   is_frame, is_cache, menu_type, visible, status, perms, icon,
   create_by, create_time, update_by, update_time, remark)
SELECT '工单管理', 0, 4, 'workorder', NULL, NULL, 'Workorder',
       1, 0, 'M', '0', '0', '', 'clipboard',
       'admin', NOW(), '', NULL, '工单业务目录'
WHERE NOT EXISTS (
  SELECT 1 FROM sys_menu
  WHERE parent_id = 0 AND path = 'workorder' AND menu_type = 'M'
);

SET @wo_root_menu_id := (
  SELECT menu_id FROM sys_menu
  WHERE parent_id = 0 AND path = 'workorder' AND menu_type = 'M'
  ORDER BY menu_id LIMIT 1
);

INSERT INTO sys_menu
  (menu_name, parent_id, order_num, path, component, query, route_name,
   is_frame, is_cache, menu_type, visible, status, perms, icon,
   create_by, create_time, update_by, update_time, remark)
SELECT '工单列表', @wo_root_menu_id, 1, 'orders', 'workorder/order/index', NULL, 'WorkorderOrders',
       1, 0, 'C', '0', '1', '', 'list',
       'admin', NOW(), '', NULL, '页面未落地，暂时停用'
WHERE @wo_root_menu_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM sys_menu
    WHERE parent_id = @wo_root_menu_id AND path = 'orders' AND menu_type = 'C'
  );

INSERT INTO sys_menu
  (menu_name, parent_id, order_num, path, component, query, route_name,
   is_frame, is_cache, menu_type, visible, status, perms, icon,
   create_by, create_time, update_by, update_time, remark)
SELECT '人员状态', @wo_root_menu_id, 2, 'engineers', 'workorder/engineer/index', NULL, 'WorkorderEngineers',
       1, 0, 'C', '0', '1', '', 'peoples',
       'admin', NOW(), '', NULL, '页面未落地，暂时停用'
WHERE @wo_root_menu_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM sys_menu
    WHERE parent_id = @wo_root_menu_id AND path = 'engineers' AND menu_type = 'C'
  );

INSERT INTO sys_menu
  (menu_name, parent_id, order_num, path, component, query, route_name,
   is_frame, is_cache, menu_type, visible, status, perms, icon,
   create_by, create_time, update_by, update_time, remark)
SELECT '分类管理', @wo_root_menu_id, 3, 'categories', 'workorder/category/index', NULL, 'WorkorderCategories',
       1, 0, 'C', '0', '1', '', 'tree-table',
       'admin', NOW(), '', NULL, '页面未落地，暂时停用'
WHERE @wo_root_menu_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM sys_menu
    WHERE parent_id = @wo_root_menu_id AND path = 'categories' AND menu_type = 'C'
  );

SET @wo_order_menu_id := (
  SELECT menu_id FROM sys_menu
  WHERE parent_id = @wo_root_menu_id AND path = 'orders' AND menu_type = 'C'
  ORDER BY menu_id LIMIT 1
);

SET @wo_engineer_menu_id := (
  SELECT menu_id FROM sys_menu
  WHERE parent_id = @wo_root_menu_id AND path = 'engineers' AND menu_type = 'C'
  ORDER BY menu_id LIMIT 1
);

SET @wo_category_menu_id := (
  SELECT menu_id FROM sys_menu
  WHERE parent_id = @wo_root_menu_id AND path = 'categories' AND menu_type = 'C'
  ORDER BY menu_id LIMIT 1
);

INSERT INTO sys_menu
  (menu_name, parent_id, order_num, path, component, query, route_name,
   is_frame, is_cache, menu_type, visible, status, perms, icon,
   create_by, create_time, update_by, update_time, remark)
SELECT seed.menu_name, seed.parent_id, seed.order_num, '', NULL, NULL, '',
       1, 0, 'F', '0', '0', seed.perms, '#',
       'admin', NOW(), '', NULL, seed.remark
FROM (
  SELECT '工单池查询' menu_name, @wo_order_menu_id parent_id, 1 order_num, 'workorder:order:list' perms, '调度管理员查询授权范围工单' remark
  UNION ALL SELECT '工单详情', @wo_order_menu_id, 2, 'workorder:order:query', '查看通过数据范围校验的工单详情'
  UNION ALL SELECT '提交工单', @wo_order_menu_id, 3, 'workorder:order:add', '报修人创建并提交工单'
  UNION ALL SELECT '取消工单', @wo_order_menu_id, 4, 'workorder:order:cancel', '取消待派单工单'
  UNION ALL SELECT '派单', @wo_order_menu_id, 5, 'workorder:order:assign', '调度管理员派单'
  UNION ALL SELECT '改派', @wo_order_menu_id, 6, 'workorder:order:reassign', '调度管理员改派'
  UNION ALL SELECT '接单', @wo_order_menu_id, 7, 'workorder:order:accept', '当前维修人员接单'
  UNION ALL SELECT '到场确认', @wo_order_menu_id, 8, 'workorder:order:arrive', '当前维修人员到场确认'
  UNION ALL SELECT '故障评估', @wo_order_menu_id, 9, 'workorder:order:assess', '当前维修人员提交评估'
  UNION ALL SELECT '更新进度', @wo_order_menu_id, 10, 'workorder:order:progress', '当前维修人员更新进度'
  UNION ALL SELECT '提交完工', @wo_order_menu_id, 11, 'workorder:order:finish', '当前维修人员提交完工'
  UNION ALL SELECT '退回处理', @wo_order_menu_id, 12, 'workorder:order:return', '报修人或调度管理员退回处理'
  UNION ALL SELECT '确认完工', @wo_order_menu_id, 13, 'workorder:order:confirm', '报修人确认完工'
  UNION ALL SELECT '上传附件', @wo_order_menu_id, 14, 'workorder:attachment:upload', '上传报修、到场、过程或完工附件'
  UNION ALL SELECT '下载附件', @wo_order_menu_id, 15, 'workorder:attachment:download', '经过工单数据权限校验后预览或下载附件'
  UNION ALL SELECT '提交评价', @wo_order_menu_id, 16, 'workorder:evaluation:add', '报修人提交一次性评价'
  UNION ALL SELECT '查看评价', @wo_order_menu_id, 17, 'workorder:evaluation:query', '查看通过数据范围校验的评价详情'
  UNION ALL SELECT '我的维修任务', @wo_order_menu_id, 18, 'workorder:order:assigned:list', '维修人员查询本人当前负责或处理过的工单'
  UNION ALL SELECT '查看人员状态', @wo_engineer_menu_id, 1, 'workorder:engineer:list', '调度管理员查询维修人员状态与负载'
  UNION ALL SELECT '更新本人状态', @wo_engineer_menu_id, 2, 'workorder:engineer:status', '维修人员更新本人工作状态'
  UNION ALL SELECT '分类列表', @wo_category_menu_id, 1, 'workorder:category:list', '查询授权范围内的分类列表'
  UNION ALL SELECT '分类详情', @wo_category_menu_id, 2, 'workorder:category:query', '查看分类详情和引用状态'
  UNION ALL SELECT '新增分类', @wo_category_menu_id, 3, 'workorder:category:add', '新增工单分类'
  UNION ALL SELECT '编辑分类', @wo_category_menu_id, 4, 'workorder:category:edit', '编辑或启停工单分类并执行引用保护'
) seed
WHERE seed.parent_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM sys_menu existing
    WHERE existing.perms = seed.perms AND existing.menu_type = 'F'
  );
-- END SOURCE: 05_workorder_menu.sql

-- ============================================================================
-- BEGIN SOURCE: 06_workorder_role_grant.sql
-- SHA256: 45bf7850ed0f28125684d900084f0eafcebaadec8354a42dad88c39ec500a345
-- ============================================================================
-- 工单三角色与最小菜单权限初始化（依赖 05-workorder-menu.sql）
-- 已存在的有效角色按 role_key 复用；仅补充缺失的角色菜单关联。

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

INSERT INTO sys_role
  (role_name, role_key, role_sort, data_scope, menu_check_strictly,
   dept_check_strictly, status, del_flag, create_by, create_time,
   update_by, update_time, remark)
SELECT '工单报修人', 'workorder_reporter', 10, '5', 1,
       1, '0', '0', 'admin', NOW(), '', NULL,
       '仅本人数据；业务层继续校验工单创建人'
WHERE NOT EXISTS (
  SELECT 1 FROM sys_role WHERE role_key = 'workorder_reporter' AND del_flag = '0'
);

INSERT INTO sys_role
  (role_name, role_key, role_sort, data_scope, menu_check_strictly,
   dept_check_strictly, status, del_flag, create_by, create_time,
   update_by, update_time, remark)
SELECT '工单维修人员', 'workorder_engineer', 20, '5', 1,
       1, '0', '0', 'admin', NOW(), '', NULL,
       '仅本人负责或处理过的工单；业务层继续校验当前处理人'
WHERE NOT EXISTS (
  SELECT 1 FROM sys_role WHERE role_key = 'workorder_engineer' AND del_flag = '0'
);

INSERT INTO sys_role
  (role_name, role_key, role_sort, data_scope, menu_check_strictly,
   dept_check_strictly, status, del_flag, create_by, create_time,
   update_by, update_time, remark)
SELECT '工单调度管理员', 'workorder_dispatcher', 30, '2', 1,
       1, '0', '0', 'admin', NOW(), '', NULL,
       '自定义部门数据范围；上线前须配置授权部门'
WHERE NOT EXISTS (
  SELECT 1 FROM sys_role WHERE role_key = 'workorder_dispatcher' AND del_flag = '0'
);

SET @wo_reporter_role_id := (
  SELECT role_id FROM sys_role
  WHERE role_key = 'workorder_reporter' AND del_flag = '0'
  ORDER BY role_id LIMIT 1
);

SET @wo_engineer_role_id := (
  SELECT role_id FROM sys_role
  WHERE role_key = 'workorder_engineer' AND del_flag = '0'
  ORDER BY role_id LIMIT 1
);

SET @wo_dispatcher_role_id := (
  SELECT role_id FROM sys_role
  WHERE role_key = 'workorder_dispatcher' AND del_flag = '0'
  ORDER BY role_id LIMIT 1
);

INSERT INTO sys_role_menu (role_id, menu_id)
SELECT @wo_reporter_role_id, menu.menu_id
FROM sys_menu menu
WHERE @wo_reporter_role_id IS NOT NULL
  AND menu.menu_type = 'F'
  AND menu.perms IN (
    'workorder:order:query',
    'workorder:order:add',
    'workorder:order:cancel',
    'workorder:order:return',
    'workorder:order:confirm',
    'workorder:attachment:upload',
    'workorder:attachment:download',
    'workorder:evaluation:add',
    'workorder:evaluation:query'
  )
  AND NOT EXISTS (
    SELECT 1 FROM sys_role_menu grant_row
    WHERE grant_row.role_id = @wo_reporter_role_id
      AND grant_row.menu_id = menu.menu_id
  );

INSERT INTO sys_role_menu (role_id, menu_id)
SELECT @wo_engineer_role_id, menu.menu_id
FROM sys_menu menu
WHERE @wo_engineer_role_id IS NOT NULL
  AND menu.menu_type = 'F'
  AND menu.perms IN (
    'workorder:order:assigned:list',
    'workorder:engineer:status',
    'workorder:order:query',
    'workorder:order:accept',
    'workorder:order:arrive',
    'workorder:order:assess',
    'workorder:order:progress',
    'workorder:order:finish',
    'workorder:attachment:upload',
    'workorder:attachment:download'
  )
  AND NOT EXISTS (
    SELECT 1 FROM sys_role_menu grant_row
    WHERE grant_row.role_id = @wo_engineer_role_id
      AND grant_row.menu_id = menu.menu_id
  );

-- 调度管理员预授予PC目录和页面定义；各页面由对应节点的增量脚本在文件落地后启用。
INSERT INTO sys_role_menu (role_id, menu_id)
SELECT @wo_dispatcher_role_id, menu.menu_id
FROM sys_menu menu
WHERE @wo_dispatcher_role_id IS NOT NULL
  AND (
    (menu.parent_id = 0 AND menu.path = 'workorder' AND menu.menu_type = 'M')
    OR (menu.menu_type = 'C' AND menu.component IN (
      'workorder/order/index',
      'workorder/engineer/index',
      'workorder/category/index'
    ))
    OR menu.perms = 'system:dept:list'
    OR (menu.menu_type = 'F' AND menu.perms IN (
      'workorder:order:list',
      'workorder:order:query',
      'workorder:order:cancel',
      'workorder:order:return',
      'workorder:order:assign',
      'workorder:order:reassign',
      'workorder:attachment:download',
      'workorder:evaluation:query',
      'workorder:engineer:list',
      'workorder:category:list',
      'workorder:category:query',
      'workorder:category:add',
      'workorder:category:edit'
    ))
  )
  AND NOT EXISTS (
    SELECT 1 FROM sys_role_menu grant_row
    WHERE grant_row.role_id = @wo_dispatcher_role_id
      AND grant_row.menu_id = menu.menu_id
  );
-- END SOURCE: 06_workorder_role_grant.sql

