-- ============================================================================
-- BEGIN SOURCE: 08_workorder_m1_core_adjust.sql
-- SHA256: 5ab515d33b72ab92c263bf5e6f377422f5652624a27ba769cc491f8d113b2cc5
-- ============================================================================
-- M1 incremental compatibility for databases initialized before pre-bound attachments were supported.
SET @schema_name = DATABASE();

SET @order_id_nullable = (
  SELECT IS_NULLABLE
  FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA = @schema_name AND TABLE_NAME = 'wo_attachment' AND COLUMN_NAME = 'order_id'
  LIMIT 1
);
SET @alter_order_id_sql = IF(
  @order_id_nullable = 'NO',
  'ALTER TABLE wo_attachment MODIFY order_id BIGINT NULL COMMENT ''工单ID，上传暂存时为空，提交后逻辑关联wo_order.id''',
  'SELECT 1'
);
PREPARE alter_order_id_stmt FROM @alter_order_id_sql;
EXECUTE alter_order_id_stmt;
DEALLOCATE PREPARE alter_order_id_stmt;

SET @object_key_index_count = (
  SELECT COUNT(*)
  FROM information_schema.STATISTICS
  WHERE TABLE_SCHEMA = @schema_name AND TABLE_NAME = 'wo_attachment'
    AND INDEX_NAME = 'uk_wo_attachment_object_key'
);
SET @add_object_key_index_sql = IF(
  @object_key_index_count = 0,
  'ALTER TABLE wo_attachment ADD UNIQUE KEY uk_wo_attachment_object_key (object_key)',
  'SELECT 1'
);
PREPARE add_object_key_index_stmt FROM @add_object_key_index_sql;
EXECUTE add_object_key_index_stmt;
DEALLOCATE PREPARE add_object_key_index_stmt;
-- END SOURCE: 08_workorder_m1_core_adjust.sql

-- ============================================================================
-- BEGIN SOURCE: 09_workorder_m1_b02.sql
-- SHA256: 018c6c31d2b588dd5cc354b1bcacec814b66aeefe8c43fad4ef136610a1d2889
-- ============================================================================
-- M1-B02 dispatch/processing slice. Safe to run repeatedly after 03-08.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

-- The PC order page now exists. Engineer/category pages intentionally remain disabled.
UPDATE sys_menu
SET status = '0', visible = '0', update_by = 'admin', update_time = NOW(),
    remark = 'M1-B02工单列表页面已启用'
WHERE menu_type = 'C' AND component = 'workorder/order/index';

-- Older installations must have the action-level idempotency constraint used by the command module.
SET @schema_name = DATABASE();
SET @action_idempotency_count = (
  SELECT COUNT(*) FROM information_schema.STATISTICS
  WHERE TABLE_SCHEMA = @schema_name AND TABLE_NAME = 'wo_action_log'
    AND INDEX_NAME = 'uk_wo_action_idempotency'
);
SET @add_action_idempotency_sql = IF(
  @action_idempotency_count = 0,
  'ALTER TABLE wo_action_log ADD UNIQUE KEY uk_wo_action_idempotency (operator_id, action_type, idempotency_key)',
  'SELECT 1'
);
PREPARE add_action_idempotency_stmt FROM @add_action_idempotency_sql;
EXECUTE add_action_idempotency_stmt;
DEALLOCATE PREPARE add_action_idempotency_stmt;
-- END SOURCE: 09_workorder_m1_b02.sql

-- ============================================================================
-- BEGIN SOURCE: 10_workorder_m1_d03.sql
-- SHA256: b76e06db1179c927bb68ffc47bf75aba0e548c1c0dcb708ef67e0555ff12f133
-- ============================================================================
-- M1-D03 人员状态与基础分类配置。依赖 03、05、06 初始化脚本，可重复执行。
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

-- 页面文件与真实接口已经落地，启用调度管理员的人员状态和分类管理菜单。
UPDATE sys_menu
SET status = '0', visible = '0', update_by = 'admin', update_time = NOW(),
    remark = 'M1-D03人员状态页面已启用'
WHERE menu_type = 'C' AND component = 'workorder/engineer/index';

UPDATE sys_menu
SET status = '0', visible = '0', update_by = 'admin', update_time = NOW(),
    remark = 'M1-D03分类管理页面已启用'
WHERE menu_type = 'C' AND component = 'workorder/category/index';

-- 兼容已经先执行过角色脚本的环境，只补充缺失授权，不产生重复关系。
SET @wo_dispatcher_role_id := (
  SELECT role_id FROM sys_role
  WHERE role_key = 'workorder_dispatcher' AND del_flag = '0'
  ORDER BY role_id LIMIT 1
);

INSERT INTO sys_role_menu (role_id, menu_id)
SELECT @wo_dispatcher_role_id, menu.menu_id
FROM sys_menu menu
WHERE @wo_dispatcher_role_id IS NOT NULL
  AND (
    (menu.menu_type = 'C' AND menu.component IN (
      'workorder/engineer/index',
      'workorder/category/index'
    ))
    OR (menu.menu_type = 'F' AND menu.perms IN (
      'workorder:engineer:list',
      'workorder:category:list',
      'workorder:category:query',
      'workorder:category:add',
      'workorder:category:edit'
    ))
  )
  AND NOT EXISTS (
    SELECT 1 FROM sys_role_menu grant_row
    WHERE grant_row.role_id = @wo_dispatcher_role_id
      AND grant_row.menu_id = menu.menu_id
  );
-- END SOURCE: 10_workorder_m1_d03.sql

-- ============================================================================
-- BEGIN SOURCE: 11_workorder_f01_sla_delay.sql
-- SHA256: 642082fabd9d050797d49a73a4e69a067016c6f6939ef5a8660196f10ab6e6f8
-- ============================================================================
-- F01 延期、SLA 与自动关闭。依赖 03-10，可重复执行。
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET @schema_name = DATABASE();

-- 工单必须快照预警提前量和延期许可，后续修改规则不得改变历史工单口径。
SET @column_count = (SELECT COUNT(*) FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA = @schema_name AND TABLE_NAME = 'wo_order' AND COLUMN_NAME = 'sla_reminder_before_min');
SET @ddl = IF(@column_count = 0,
  'ALTER TABLE wo_order ADD COLUMN sla_reminder_before_min INT NOT NULL DEFAULT 15 COMMENT ''SLA预警提前分钟数快照'' AFTER finish_deadline',
  'SELECT 1');
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @column_count = (SELECT COUNT(*) FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA = @schema_name AND TABLE_NAME = 'wo_order' AND COLUMN_NAME = 'sla_allow_extension');
SET @ddl = IF(@column_count = 0,
  'ALTER TABLE wo_order ADD COLUMN sla_allow_extension CHAR(1) NOT NULL DEFAULT ''1'' COMMENT ''是否允许延期快照：0否 1是'' AFTER sla_reminder_before_min',
  'SELECT 1');
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;

UPDATE wo_order o
JOIN wo_sla_rule r ON r.id = o.sla_rule_id
SET o.sla_reminder_before_min = r.reminder_before_min,
    o.sla_allow_extension = r.allow_extension
WHERE o.del_flag = '0';

CREATE TABLE IF NOT EXISTS wo_delay_request (
  id                    BIGINT        NOT NULL AUTO_INCREMENT COMMENT '延期申请ID',
  order_id              BIGINT        NOT NULL COMMENT '工单ID',
  order_no              VARCHAR(32)   NOT NULL COMMENT '工单编号快照',
  order_title           VARCHAR(128)  NOT NULL COMMENT '工单标题快照',
  engineer_id           BIGINT        NOT NULL COMMENT '申请维修人员ID',
  engineer_name         VARCHAR(64)   NOT NULL COMMENT '申请维修人员姓名快照',
  original_deadline     DATETIME      NOT NULL COMMENT '申请时有效完成截止时间',
  requested_deadline    DATETIME      NOT NULL COMMENT '申请的新截止时间',
  request_reason        VARCHAR(500)  NOT NULL COMMENT '延期原因',
  status                VARCHAR(16)   NOT NULL COMMENT 'PENDING/APPROVED/REJECTED/CANCELLED',
  decided_by            BIGINT        NULL COMMENT '审批人ID',
  decided_by_name       VARCHAR(64)   NULL COMMENT '审批人姓名快照',
  decided_at            DATETIME      NULL COMMENT '审批时间',
  decision_reason       VARCHAR(500)  NULL COMMENT '审批说明或拒绝原因',
  create_time           DATETIME      NOT NULL COMMENT '申请时间',
  update_time           DATETIME      NULL COMMENT '更新时间',
  pending_order_id      BIGINT GENERATED ALWAYS AS
                         (CASE WHEN status = 'PENDING' THEN order_id ELSE NULL END) STORED,
  PRIMARY KEY (id),
  UNIQUE KEY uk_wo_delay_pending_order (pending_order_id),
  KEY idx_wo_delay_order (order_id, create_time),
  KEY idx_wo_delay_status (status, create_time),
  KEY idx_wo_delay_engineer (engineer_id, create_time),
  CONSTRAINT chk_wo_delay_deadline CHECK (requested_deadline > original_deadline)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='工单延期申请';

-- 新增 F01 页面与按钮权限。
SET @wo_root_menu_id := (
  SELECT menu_id FROM sys_menu WHERE parent_id = 0 AND path = 'workorder' AND menu_type = 'M'
  ORDER BY menu_id LIMIT 1
);

INSERT INTO sys_menu
  (menu_name, parent_id, order_num, path, component, query, route_name, is_frame, is_cache,
   menu_type, visible, status, perms, icon, create_by, create_time, update_by, update_time, remark)
SELECT '延期审批', @wo_root_menu_id, 4, 'delay-requests', 'workorder/delay/index', NULL,
       'WorkorderDelayRequests', 1, 0, 'C', '0', '0', '', 'time', 'admin', NOW(), '', NULL, 'F01延期审批'
WHERE @wo_root_menu_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM sys_menu WHERE parent_id = @wo_root_menu_id AND path = 'delay-requests' AND menu_type = 'C'
);

INSERT INTO sys_menu
  (menu_name, parent_id, order_num, path, component, query, route_name, is_frame, is_cache,
   menu_type, visible, status, perms, icon, create_by, create_time, update_by, update_time, remark)
SELECT 'SLA规则', @wo_root_menu_id, 5, 'sla-rules', 'workorder/sla/index', NULL,
       'WorkorderSlaRules', 1, 0, 'C', '0', '0', '', 'timer', 'admin', NOW(), '', NULL, 'F01 SLA规则配置'
WHERE @wo_root_menu_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM sys_menu WHERE parent_id = @wo_root_menu_id AND path = 'sla-rules' AND menu_type = 'C'
);

SET @wo_order_menu_id := (SELECT menu_id FROM sys_menu
  WHERE parent_id = @wo_root_menu_id AND path = 'orders' AND menu_type = 'C' ORDER BY menu_id LIMIT 1);
SET @wo_delay_menu_id := (SELECT menu_id FROM sys_menu
  WHERE parent_id = @wo_root_menu_id AND path = 'delay-requests' AND menu_type = 'C' ORDER BY menu_id LIMIT 1);
SET @wo_sla_menu_id := (SELECT menu_id FROM sys_menu
  WHERE parent_id = @wo_root_menu_id AND path = 'sla-rules' AND menu_type = 'C' ORDER BY menu_id LIMIT 1);

INSERT INTO sys_menu
  (menu_name, parent_id, order_num, path, component, query, route_name, is_frame, is_cache,
   menu_type, visible, status, perms, icon, create_by, create_time, update_by, update_time, remark)
SELECT seed.menu_name, seed.parent_id, seed.order_num, '', NULL, NULL, '', 1, 0, 'F', '0', '0',
       seed.perms, '#', 'admin', NOW(), '', NULL, seed.remark
FROM (
  SELECT '申请延期' menu_name, @wo_order_menu_id parent_id, 19 order_num, 'workorder:delay:add' perms, '当前维修人员申请延期' remark
  UNION ALL SELECT '延期详情', @wo_delay_menu_id, 1, 'workorder:delay:query', '查看可见工单的延期申请'
  UNION ALL SELECT '延期列表', @wo_delay_menu_id, 2, 'workorder:delay:list', '调度管理员查询授权范围延期申请'
  UNION ALL SELECT '延期审批', @wo_delay_menu_id, 3, 'workorder:delay:approve', '调度管理员审批延期申请'
  UNION ALL SELECT 'SLA列表', @wo_sla_menu_id, 1, 'workorder:sla:list', '查询SLA规则'
  UNION ALL SELECT 'SLA详情', @wo_sla_menu_id, 2, 'workorder:sla:query', '查看SLA规则详情'
  UNION ALL SELECT '新增SLA', @wo_sla_menu_id, 3, 'workorder:sla:add', '新增SLA规则'
  UNION ALL SELECT '编辑SLA', @wo_sla_menu_id, 4, 'workorder:sla:edit', '编辑或启停SLA规则'
) seed
WHERE seed.parent_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM sys_menu existing WHERE existing.perms = seed.perms AND existing.menu_type = 'F'
);

SET @wo_reporter_role_id := (SELECT role_id FROM sys_role WHERE role_key = 'workorder_reporter' AND del_flag = '0' ORDER BY role_id LIMIT 1);
SET @wo_engineer_role_id := (SELECT role_id FROM sys_role WHERE role_key = 'workorder_engineer' AND del_flag = '0' ORDER BY role_id LIMIT 1);
SET @wo_dispatcher_role_id := (SELECT role_id FROM sys_role WHERE role_key = 'workorder_dispatcher' AND del_flag = '0' ORDER BY role_id LIMIT 1);

INSERT INTO sys_role_menu (role_id, menu_id)
SELECT grants.role_id, menu.menu_id
FROM (
  SELECT @wo_reporter_role_id role_id, 'workorder:delay:query' perms
  UNION ALL SELECT @wo_engineer_role_id, 'workorder:delay:add'
  UNION ALL SELECT @wo_engineer_role_id, 'workorder:delay:query'
  UNION ALL SELECT @wo_dispatcher_role_id, 'workorder:delay:query'
  UNION ALL SELECT @wo_dispatcher_role_id, 'workorder:delay:list'
  UNION ALL SELECT @wo_dispatcher_role_id, 'workorder:delay:approve'
  UNION ALL SELECT @wo_dispatcher_role_id, 'workorder:sla:list'
  UNION ALL SELECT @wo_dispatcher_role_id, 'workorder:sla:query'
  UNION ALL SELECT @wo_dispatcher_role_id, 'workorder:sla:add'
  UNION ALL SELECT @wo_dispatcher_role_id, 'workorder:sla:edit'
) grants
JOIN sys_menu menu ON menu.perms = grants.perms AND menu.menu_type = 'F'
WHERE grants.role_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM sys_role_menu existing
  WHERE existing.role_id = grants.role_id AND existing.menu_id = menu.menu_id
);

INSERT INTO sys_role_menu (role_id, menu_id)
SELECT @wo_dispatcher_role_id, menu.menu_id FROM sys_menu menu
WHERE @wo_dispatcher_role_id IS NOT NULL
  AND menu.menu_type = 'C' AND menu.component IN ('workorder/delay/index', 'workorder/sla/index')
  AND NOT EXISTS (SELECT 1 FROM sys_role_menu existing
    WHERE existing.role_id = @wo_dispatcher_role_id AND existing.menu_id = menu.menu_id);

-- Quartz 调用适配器只负责进入 SLA 生命周期模块，禁止并发执行同一任务。
INSERT INTO sys_job
  (job_name, job_group, invoke_target, cron_expression, misfire_policy, concurrent, status,
   create_by, create_time, update_by, update_time, remark)
SELECT '工单SLA预警与超时扫描', 'WORKORDER', 'workOrderSlaTask.scan', '0 0/1 * * * ?', '3', '1', '0',
       'admin', NOW(), '', NULL, '每分钟刷新正交SLA标志并记录首次预警/超时审计'
WHERE NOT EXISTS (SELECT 1 FROM sys_job WHERE job_group = 'WORKORDER' AND invoke_target = 'workOrderSlaTask.scan');

INSERT INTO sys_job
  (job_name, job_group, invoke_target, cron_expression, misfire_policy, concurrent, status,
   create_by, create_time, update_by, update_time, remark)
SELECT '工单评价窗口自动关闭', 'WORKORDER', 'workOrderSlaTask.autoClose', '0 15 2 * * ?', '3', '1', '0',
       'admin', NOW(), '', NULL, '每天扫描超过评价窗口仍未评价的已完成工单'
WHERE NOT EXISTS (SELECT 1 FROM sys_job WHERE job_group = 'WORKORDER' AND invoke_target = 'workOrderSlaTask.autoClose');
-- END SOURCE: 11_workorder_f01_sla_delay.sql

-- ============================================================================
-- BEGIN SOURCE: 12_workorder_f02_notification.sql
-- SHA256: 11f788e294258cfc994f0c989c72316bf215196b79564818bd6a840032480a8e
-- ============================================================================
-- F02 工单通知与站内消息增量脚本。依赖 03-11，可重复执行。
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

-- 通知模板按事件和渠道唯一；当前只初始化站内信模板，SMS 渠道由后续渠道接入时补充。
CREATE TABLE IF NOT EXISTS wo_notification_template (
  id                    BIGINT        NOT NULL AUTO_INCREMENT COMMENT '通知模板ID',
  event_code            VARCHAR(64)   NOT NULL COMMENT '通知事件编码',
  channel               VARCHAR(16)   NOT NULL COMMENT '通知渠道：IN_APP/SMS',
  category              VARCHAR(32)   NOT NULL COMMENT '通知分类',
  template_name         VARCHAR(64)   NOT NULL COMMENT '模板名称',
  title_template        VARCHAR(200)  NOT NULL COMMENT '标题模板',
  content_template      VARCHAR(2000) NOT NULL COMMENT '内容模板',
  enabled_flag          CHAR(1)       NOT NULL DEFAULT '1' COMMENT '是否启用：0否 1是',
  max_retry             INT           NOT NULL DEFAULT 5 COMMENT '最大重试次数',
  create_by             VARCHAR(64)   NOT NULL DEFAULT '' COMMENT '创建者',
  create_time           DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  update_by             VARCHAR(64)   NOT NULL DEFAULT '' COMMENT '更新者',
  update_time           DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  remark                VARCHAR(500)  NULL COMMENT '备注',
  PRIMARY KEY (id),
  UNIQUE KEY uk_wo_notification_template_event_channel (event_code, channel),
  CONSTRAINT chk_wo_notification_template_enabled CHECK (enabled_flag IN ('0', '1')),
  CONSTRAINT chk_wo_notification_template_retry CHECK (max_retry >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='工单通知模板';

-- 通知任务保存投递快照，业务层以 event_key/channel/recipient_id 保证同一事件不重复投递。
CREATE TABLE IF NOT EXISTS wo_notification_task (
  id                    BIGINT        NOT NULL AUTO_INCREMENT COMMENT '通知任务ID',
  event_key             VARCHAR(128)  NOT NULL COMMENT '业务事件幂等键',
  event_code            VARCHAR(64)   NOT NULL COMMENT '通知事件编码',
  category              VARCHAR(32)   NOT NULL COMMENT '通知分类',
  channel               VARCHAR(16)   NOT NULL COMMENT '通知渠道：IN_APP/SMS',
  recipient_id          BIGINT        NOT NULL COMMENT '接收人用户ID',
  recipient_name        VARCHAR(64)   NULL COMMENT '接收人姓名快照',
  recipient_address     VARCHAR(255)  NULL COMMENT '接收地址快照',
  business_type         VARCHAR(32)   NULL COMMENT '业务类型',
  business_id           BIGINT        NULL COMMENT '业务ID',
  order_no              VARCHAR(32)   NULL COMMENT '工单编号快照',
  title                 VARCHAR(200)  NOT NULL COMMENT '通知标题快照',
  content               VARCHAR(2000) NOT NULL COMMENT '通知内容快照',
  route_path            VARCHAR(255)  NULL COMMENT '站内信跳转路径',
  route_params          JSON          NULL COMMENT '站内信跳转参数',
  status                VARCHAR(16)   NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING/PROCESSING/RETRY/SUCCESS/DEAD',
  retry_count           INT           NOT NULL DEFAULT 0 COMMENT '已重试次数',
  max_retry             INT           NOT NULL DEFAULT 5 COMMENT '最大重试次数',
  next_retry_at         DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '下次可投递时间',
  locked_by             VARCHAR(64)   NULL COMMENT '处理节点标识',
  locked_at             DATETIME      NULL COMMENT '加锁时间',
  last_error            VARCHAR(2000) NULL COMMENT '最近一次失败原因',
  sent_at               DATETIME      NULL COMMENT '成功投递时间',
  create_by             VARCHAR(64)   NOT NULL DEFAULT '' COMMENT '创建者',
  create_time           DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  update_by             VARCHAR(64)   NOT NULL DEFAULT '' COMMENT '更新者',
  update_time           DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (id),
  UNIQUE KEY uk_wo_notification_task_event_recipient (event_key, channel, recipient_id),
  KEY idx_wo_notification_task_due (status, next_retry_at, id),
  KEY idx_wo_notification_task_business (business_type, business_id, order_no, create_time),
  KEY idx_wo_notification_task_recipient (recipient_id, status, create_time),
  CONSTRAINT chk_wo_notification_task_status CHECK (status IN ('PENDING', 'PROCESSING', 'RETRY', 'SUCCESS', 'DEAD')),
  CONSTRAINT chk_wo_notification_task_retry_count CHECK (retry_count >= 0),
  CONSTRAINT chk_wo_notification_task_max_retry CHECK (max_retry >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='工单通知投递任务';

-- 站内信是通知任务成功后的用户消息视图；每个任务最多生成一条站内信。
CREATE TABLE IF NOT EXISTS wo_notification_message (
  id                    BIGINT        NOT NULL AUTO_INCREMENT COMMENT '站内消息ID',
  task_id               BIGINT        NOT NULL COMMENT '通知任务ID',
  recipient_id          BIGINT        NOT NULL COMMENT '接收人用户ID',
  category              VARCHAR(32)   NOT NULL COMMENT '通知分类',
  event_code            VARCHAR(64)   NOT NULL COMMENT '通知事件编码',
  title                 VARCHAR(200)  NOT NULL COMMENT '消息标题',
  content               VARCHAR(2000) NOT NULL COMMENT '消息内容',
  business_type         VARCHAR(32)   NULL COMMENT '业务类型',
  business_id           BIGINT        NULL COMMENT '业务ID',
  order_no              VARCHAR(32)   NULL COMMENT '工单编号快照',
  route_path            VARCHAR(255)  NULL COMMENT '站内信跳转路径',
  route_params          JSON          NULL COMMENT '站内信跳转参数',
  read_flag             CHAR(1)       NOT NULL DEFAULT '0' COMMENT '是否已读：0否 1是',
  read_at               DATETIME      NULL COMMENT '读取时间',
  create_time           DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (id),
  UNIQUE KEY uk_wo_notification_message_task (task_id),
  KEY idx_wo_notification_message_recipient_read_time (recipient_id, read_flag, create_time),
  KEY idx_wo_notification_message_recipient_category_time (recipient_id, category, create_time),
  CONSTRAINT chk_wo_notification_message_read CHECK (read_flag IN ('0', '1'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='工单站内消息';

-- 初始化站内信模板。模板占位符仅使用 orderNo/title/operatorName/reason/deadline。
INSERT INTO wo_notification_template
  (event_code, channel, category, template_name, title_template, content_template,
   enabled_flag, max_retry, create_by, create_time, update_by, update_time, remark)
SELECT seed.event_code, seed.channel, seed.category, seed.template_name,
       seed.title_template, seed.content_template, seed.enabled_flag, seed.max_retry,
       'admin', NOW(), '', NOW(), seed.remark
FROM (
  SELECT 'SUBMIT' event_code, 'IN_APP' channel, 'WORK_ORDER' category, '工单提交通知' template_name,
         '工单已提交：${orderNo}' title_template,
         '工单“${title}”已提交，等待调度处理。' content_template,
         '1' enabled_flag, 5 max_retry, 'F02工单提交站内信' remark
  UNION ALL SELECT 'ASSIGN', 'IN_APP', 'WORK_ORDER', '工单派单通知',
         '工单已派单：${orderNo}', '工单“${title}”已由${operatorName}分配给你，请及时处理。', '1', 5, 'F02工单派单站内信'
  UNION ALL SELECT 'ACCEPT', 'IN_APP', 'WORK_ORDER', '工单接单通知',
         '维修人员已接单：${orderNo}', '工单“${title}”已由${operatorName}接单。', '1', 5, 'F02工单接单站内信'
  UNION ALL SELECT 'ARRIVE', 'IN_APP', 'WORK_ORDER', '维修人员到场通知',
         '维修人员已到场：${orderNo}', '工单“${title}”的维修人员已到场处理。', '1', 5, 'F02到场站内信'
  UNION ALL SELECT 'PROGRESS', 'IN_APP', 'WORK_ORDER', '工单进度通知',
         '工单进度已更新：${orderNo}', '工单“${title}”有新的处理进度。', '1', 5, 'F02进度站内信'
  UNION ALL SELECT 'REASSIGN_OLD', 'IN_APP', 'WORK_ORDER', '工单改派原处理人通知',
         '工单已改派：${orderNo}', '工单“${title}”已改派给其他维修人员。', '1', 5, 'F02工单改派原处理人站内信'
  UNION ALL SELECT 'REASSIGN_NEW', 'IN_APP', 'WORK_ORDER', '工单改派新处理人通知',
         '工单待处理：${orderNo}', '工单“${title}”已改派给你，请及时处理。', '1', 5, 'F02工单改派新处理人站内信'
  UNION ALL SELECT 'FINISH', 'IN_APP', 'WORK_ORDER', '工单完工通知',
         '工单已完工：${orderNo}', '工单“${title}”已由${operatorName}提交完工。', '1', 5, 'F02工单完工站内信'
  UNION ALL SELECT 'RETURN', 'IN_APP', 'WORK_ORDER', '工单退回通知',
         '工单已退回：${orderNo}', '工单“${title}”被退回，原因：${reason}。', '1', 5, 'F02工单退回站内信'
  UNION ALL SELECT 'CONFIRM', 'IN_APP', 'WORK_ORDER', '完工确认通知',
         '完工已确认：${orderNo}', '工单“${title}”已由报修人确认完成。', '1', 5, 'F02完工确认站内信'
  UNION ALL SELECT 'EVALUATE', 'IN_APP', 'WORK_ORDER', '工单评价通知',
         '收到工单评价：${orderNo}', '工单“${title}”已收到报修人评价。', '1', 5, 'F02评价站内信'
  UNION ALL SELECT 'CANCEL', 'IN_APP', 'WORK_ORDER', '工单取消通知',
         '工单已取消：${orderNo}', '工单“${title}”已取消，原因：${reason}。', '1', 5, 'F02取消站内信'
  UNION ALL SELECT 'DELAY_REQUEST', 'IN_APP', 'APPROVAL', '延期申请通知',
         '工单延期待审批：${orderNo}', '工单“${title}”申请延期至${deadline}，原因：${reason}。', '1', 5, 'F02延期申请站内信'
  UNION ALL SELECT 'DELAY_APPROVED', 'IN_APP', 'APPROVAL', '延期通过通知',
         '工单延期已通过：${orderNo}', '工单“${title}”已批准延期至${deadline}。', '1', 5, 'F02延期通过站内信'
  UNION ALL SELECT 'DELAY_REJECTED', 'IN_APP', 'APPROVAL', '延期驳回通知',
         '工单延期未通过：${orderNo}', '工单“${title}”延期申请未通过，原因：${reason}。', '1', 5, 'F02延期驳回站内信'
  UNION ALL SELECT 'SLA_WARNING', 'IN_APP', 'SYSTEM', 'SLA预警通知',
         '工单即将超时：${orderNo}', '工单“${title}”的处理期限为${deadline}，请及时处理。', '1', 5, 'F02 SLA预警站内信'
  UNION ALL SELECT 'SLA_OVERDUE', 'IN_APP', 'SYSTEM', 'SLA超时通知',
         '工单已超时：${orderNo}', '工单“${title}”已超过处理期限${deadline}。', '1', 5, 'F02 SLA超时站内信'
  UNION ALL SELECT 'AUTO_CLOSE', 'IN_APP', 'SYSTEM', '工单自动关闭通知',
         '工单已自动关闭：${orderNo}', '工单“${title}”在完成后超过评价窗口，已自动关闭。', '1', 5, 'F02工单自动关闭站内信'
) seed
WHERE NOT EXISTS (
  SELECT 1 FROM wo_notification_template existing
  WHERE existing.event_code = seed.event_code AND existing.channel = seed.channel
);

-- 只创建 F 类型权限，不创建 F02/P09 页面菜单；页面菜单由后续页面增量另行处理。
SET @wo_root_menu_id := (
  SELECT menu_id FROM sys_menu
  WHERE parent_id = 0 AND path = 'workorder' AND menu_type = 'M'
  ORDER BY menu_id LIMIT 1
);

INSERT INTO sys_menu
  (menu_name, parent_id, order_num, path, component, query, route_name, is_frame, is_cache,
   menu_type, visible, status, perms, icon, create_by, create_time, update_by, update_time, remark)
SELECT seed.menu_name, @wo_root_menu_id, seed.order_num, '', NULL, NULL, '',
       1, 0, 'F', '0', '0', seed.perms, '#', 'admin', NOW(), '', NULL, seed.remark
FROM (
  SELECT '消息列表' menu_name, 20 order_num, 'workorder:notification:list' perms, 'F02消息列表权限' remark
  UNION ALL SELECT '读取消息', 21, 'workorder:notification:read', 'F02消息读取权限'
  UNION ALL SELECT '发送记录', 22, 'workorder:message:record', 'F02通知发送记录权限'
  UNION ALL SELECT '重试消息', 23, 'workorder:message:retry', 'F02通知任务重试权限'
) seed
WHERE @wo_root_menu_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM sys_menu existing
    WHERE existing.perms = seed.perms AND existing.menu_type = 'F'
  );

-- 严格按 role_key 查找三类工单角色；三类角色均可查看消息，只有 dispatcher 可管理发送记录和重试。
SET @wo_reporter_role_id := (
  SELECT role_id FROM sys_role
  WHERE role_key = 'workorder_reporter' AND del_flag = '0'
  ORDER BY role_id LIMIT 1
);
SET @wo_engineer_role_id := (
  SELECT role_id FROM sys_role
  WHERE role_key = 'workorder_engineer' AND del_flag = '0'
  ORDER BY role_id LIMIT 1
);
SET @wo_dispatcher_role_id := (
  SELECT role_id FROM sys_role
  WHERE role_key = 'workorder_dispatcher' AND del_flag = '0'
  ORDER BY role_id LIMIT 1
);

INSERT INTO sys_role_menu (role_id, menu_id)
SELECT grants.role_id, menu.menu_id
FROM (
  SELECT @wo_reporter_role_id role_id, 'workorder:notification:list' perms
  UNION ALL SELECT @wo_reporter_role_id, 'workorder:notification:read'
  UNION ALL SELECT @wo_engineer_role_id, 'workorder:notification:list'
  UNION ALL SELECT @wo_engineer_role_id, 'workorder:notification:read'
  UNION ALL SELECT @wo_dispatcher_role_id, 'workorder:notification:list'
  UNION ALL SELECT @wo_dispatcher_role_id, 'workorder:notification:read'
  UNION ALL SELECT @wo_dispatcher_role_id, 'workorder:message:record'
  UNION ALL SELECT @wo_dispatcher_role_id, 'workorder:message:retry'
) grants
JOIN sys_menu menu ON menu.perms = grants.perms AND menu.menu_type = 'F'
WHERE grants.role_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM sys_role_menu existing
    WHERE existing.role_id = grants.role_id AND existing.menu_id = menu.menu_id
  );

-- sys_job 来自 ry_20250522.sql：job_id 自增，以下为其余字段的显式列清单。
-- 任务禁止并发，定期派发 PENDING/RETRY 通知任务。
INSERT INTO sys_job
  (job_name, job_group, invoke_target, cron_expression, misfire_policy, concurrent, status,
   create_by, create_time, update_by, update_time, remark)
SELECT '工单通知任务派发', 'WORKORDER', 'workOrderNotificationTask.dispatch', '0/10 * * * * ?',
       '3', '1', '0', 'admin', NOW(), '', NULL, '每10秒派发到期的工单通知任务'
WHERE NOT EXISTS (
  SELECT 1 FROM sys_job
  WHERE job_group = 'WORKORDER' AND invoke_target = 'workOrderNotificationTask.dispatch'
);
-- END SOURCE: 12_workorder_f02_notification.sql

-- ============================================================================
-- BEGIN SOURCE: 13_workorder_f04_operations.sql
-- SHA256: 89dbffae279f9f33addc7075d16ff542cddae29e7baffe0afe965882f1707036
-- ============================================================================
-- F04 PC配置、消息、统计与绩效增量脚本。依赖 03-12，可重复执行。
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

-- 只保存短信账户的脱敏展示信息、运营设置和最后成功快照，供应商密钥由部署环境持有。
CREATE TABLE IF NOT EXISTS wo_sms_account_setting (
  id                    BIGINT         NOT NULL COMMENT '固定主键，当前仅使用1',
  configured_flag       CHAR(1)        NOT NULL DEFAULT '0' COMMENT '供应商是否已配置：0否 1是',
  provider_code         VARCHAR(32)    NULL COMMENT '供应商编码',
  provider_name         VARCHAR(64)    NULL COMMENT '供应商名称',
  account_alias         VARCHAR(64)    NULL COMMENT '账户别名',
  credential_mask       VARCHAR(128)   NULL COMMENT '不可逆脱敏后的凭据标识',
  account_status        VARCHAR(24)    NOT NULL DEFAULT 'UNCONFIGURED' COMMENT 'UNCONFIGURED/NORMAL/WARNING/UNAVAILABLE',
  available_balance     DECIMAL(14,2)  NULL COMMENT '最近一次成功查询的可用余额',
  warning_threshold     DECIMAL(14,2)  NOT NULL DEFAULT 100.00 COMMENT '余额预警阈值',
  retry_enabled         CHAR(1)        NOT NULL DEFAULT '0' COMMENT '短信失败自动重试：0关闭 1开启',
  last_success_time     DATETIME       NULL COMMENT '最近一次余额查询成功时间',
  last_error            VARCHAR(500)   NULL COMMENT '最近一次刷新失败摘要，不含密钥和完整请求',
  create_by             VARCHAR(64)    NOT NULL DEFAULT '' COMMENT '创建者',
  create_time           DATETIME       NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  update_by             VARCHAR(64)    NOT NULL DEFAULT '' COMMENT '更新者',
  update_time           DATETIME       NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (id),
  CONSTRAINT chk_wo_sms_configured CHECK (configured_flag IN ('0','1')),
  CONSTRAINT chk_wo_sms_retry CHECK (retry_enabled IN ('0','1')),
  CONSTRAINT chk_wo_sms_threshold CHECK (warning_threshold >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='短信账户脱敏快照与运营设置';

INSERT INTO wo_sms_account_setting
  (id, configured_flag, account_status, warning_threshold, retry_enabled, create_by, create_time)
SELECT 1, '0', 'UNCONFIGURED', 100.00, '0', 'admin', NOW()
WHERE NOT EXISTS (SELECT 1 FROM wo_sms_account_setting WHERE id = 1);

SET @wo_root_menu_id := (
  SELECT menu_id FROM sys_menu
  WHERE parent_id = 0 AND path = 'workorder' AND menu_type = 'M'
  ORDER BY menu_id LIMIT 1
);

-- 将 F04 页面集中到运营管理目录，避免继续把所有页面平铺在工单根目录下。
INSERT INTO sys_menu
  (menu_name, parent_id, order_num, path, component, query, route_name,
   is_frame, is_cache, menu_type, visible, status, perms, icon,
   create_by, create_time, update_by, update_time, remark)
SELECT '运营管理', @wo_root_menu_id, 20, 'operations', NULL, NULL, 'WorkorderOperations',
       1, 0, 'M', '0', '0', '', 'dashboard',
       'admin', NOW(), '', NULL, 'F04运营页面目录'
WHERE @wo_root_menu_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM sys_menu WHERE parent_id = @wo_root_menu_id AND path = 'operations' AND menu_type = 'M'
  );

SET @wo_operations_menu_id := (
  SELECT menu_id FROM sys_menu
  WHERE parent_id = @wo_root_menu_id AND path = 'operations' AND menu_type = 'M'
  ORDER BY menu_id LIMIT 1
);

INSERT INTO sys_menu
  (menu_name, parent_id, order_num, path, component, query, route_name,
   is_frame, is_cache, menu_type, visible, status, perms, icon,
   create_by, create_time, update_by, update_time, remark)
SELECT seed.menu_name, @wo_operations_menu_id, seed.order_num, seed.path, seed.component, NULL, seed.route_name,
       1, 0, 'C', '0', '0', seed.perms, seed.icon,
       'admin', NOW(), '', NULL, seed.remark
FROM (
  SELECT '维修绩效' menu_name, 1 order_num, 'performance' path, 'workorder/performance/index' component,
         'WorkorderPerformance' route_name, 'workorder:performance:view' perms, 'chart' icon, 'F04维修绩效页面' remark
  UNION ALL SELECT '消息管理', 2, 'messages', 'workorder/message/index',
         'WorkorderMessages', 'workorder:message:template', 'message', 'F04消息模板与发送记录页面'
  UNION ALL SELECT '短信账户', 3, 'sms', 'workorder/sms/index',
         'WorkorderSms', 'workorder:sms:view', 'phone', 'F04短信账户页面'
) seed
WHERE @wo_operations_menu_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM sys_menu existing
    WHERE existing.parent_id = @wo_operations_menu_id AND existing.path = seed.path AND existing.menu_type = 'C'
  );

SET @wo_message_menu_id := (
  SELECT menu_id FROM sys_menu WHERE parent_id = @wo_operations_menu_id AND path = 'messages' AND menu_type = 'C'
  ORDER BY menu_id LIMIT 1
);
SET @wo_sms_menu_id := (
  SELECT menu_id FROM sys_menu WHERE parent_id = @wo_operations_menu_id AND path = 'sms' AND menu_type = 'C'
  ORDER BY menu_id LIMIT 1
);

INSERT INTO sys_menu
  (menu_name, parent_id, order_num, path, component, query, route_name,
   is_frame, is_cache, menu_type, visible, status, perms, icon,
   create_by, create_time, update_by, update_time, remark)
SELECT seed.menu_name, seed.parent_id, seed.order_num, '', NULL, NULL, '',
       1, 0, 'F', '0', '0', seed.perms, '#',
       'admin', NOW(), '', NULL, seed.remark
FROM (
  SELECT '运营驾驶舱' menu_name, @wo_root_menu_id parent_id, 30 order_num,
         'workorder:dashboard:view' perms, 'F04首页驾驶舱查询权限' remark
  UNION ALL SELECT '发送记录', @wo_message_menu_id, 1, 'workorder:message:record', 'F04通知发送记录查询权限'
  UNION ALL SELECT '重试消息', @wo_message_menu_id, 2, 'workorder:message:retry', 'F04通知任务人工重试权限'
  UNION ALL SELECT '编辑短信设置', @wo_sms_menu_id, 1, 'workorder:sms:edit', 'F04短信运营设置权限'
  UNION ALL SELECT '刷新短信账户', @wo_sms_menu_id, 2, 'workorder:sms:refresh', 'F04短信余额刷新权限'
) seed
WHERE seed.parent_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM sys_menu existing WHERE existing.perms = seed.perms AND existing.menu_type = 'F'
  );

-- 调度管理员承担运营管理职责；admin 角色仍使用若依内置的超级管理员授权。
SET @wo_dispatcher_role_id := (
  SELECT role_id FROM sys_role WHERE role_key = 'workorder_dispatcher' AND del_flag = '0'
  ORDER BY role_id LIMIT 1
);

INSERT INTO sys_role_menu (role_id, menu_id)
SELECT @wo_dispatcher_role_id, menu.menu_id
FROM sys_menu menu
WHERE @wo_dispatcher_role_id IS NOT NULL
  AND (menu.menu_id = @wo_operations_menu_id
       OR menu.parent_id = @wo_operations_menu_id
       OR menu.perms IN ('workorder:dashboard:view','workorder:message:record','workorder:message:retry',
                         'workorder:sms:edit','workorder:sms:refresh'))
  AND NOT EXISTS (
    SELECT 1 FROM sys_role_menu existing
    WHERE existing.role_id = @wo_dispatcher_role_id AND existing.menu_id = menu.menu_id
  );
-- END SOURCE: 13_workorder_f04_operations.sql

